1	//! Producing endpoint: [`Producer`] claims the next slot by its
2	//! seq word, the [`WriteSlot`] guard writes it in place and
3	//! commits through the same word.
4	
5	use core::marker::PhantomData;
6	use core::ops::{Deref, DerefMut};
7	use core::sync::atomic::{AtomicU32, Ordering};
8	use zerocopy::{FromBytes, IntoBytes, KnownLayout};
9	
10	use super::Header;
11	use crate::{Full, USER_WORDS, check_type, slot_ptr};
12	
13	/// The producing endpoint: `reserve_slot_with`, write in
14	/// place, `commit`.
15	pub struct Producer<'a> {
16	    /// The ring's control block.
17	    header: &'a Header,
18	    /// Base of the per-slot sequence array.
19	    seqs: *const AtomicU32,
20	    /// Base of the slot array.
21	    slots: *mut u8,
22	    /// Geometry snapshot (see [`Ring`](super::Ring)).
23	    slot_size: u32,
24	    /// Geometry snapshot; commit stores `pos + capacity + 1`.
25	    capacity: u32,
26	    /// Slot-position mask (`capacity - 1`).
27	    mask: u32,
28	    _region: PhantomData<&'a [u8]>,
29	}
30	
31	// SAFETY: the handle owns the producer role; the shared state it
32	// touches (seqs, its index) is atomic, and slot writes are
33	// handed off with Release/Acquire ordering.
34	unsafe impl Send for Producer<'_> {}
35	
36	impl<'a> Producer<'a> {
37	    /// Build the handle from [`Ring::split`](super::Ring::split)'s
38	    /// geometry snapshot.
39	    pub(super) fn new(
40	        header: &'a Header,
41	        seqs: *const AtomicU32,
42	        slots: *mut u8,
43	        slot_size: u32,
44	        capacity: u32,
45	        mask: u32,
46	    ) -> Self {
47	        Producer {
48	            header,
49	            seqs,
50	            slots,
51	            slot_size,
52	            capacity,
53	            mask,
54	            _region: PhantomData,
55	        }
56	    }
57	
58	    /// The header's app-owned scratch line — same contract as
59	    /// the v0 endpoints' `user()`.
60	    pub fn user(&self) -> &[AtomicU32; USER_WORDS] {
61	        &self.header.user
62	    }
63	
64	    /// The seq word for free-running position `idx`.
65	    fn seq(&self, idx: u32) -> &AtomicU32 {
66	        // SAFETY: idx is masked to < capacity, inside the seq
67	        // array validated at init/attach.
68	        unsafe { &*self.seqs.add((idx & self.mask) as usize) }
69	    }
70	
71	    /// Reserve the next free slot as a `&mut T`, applying an
72	    /// injected wait policy: retry until the slot frees up or
73	    /// the policy gives up → [`Full`].
74	    ///
75	    /// - The slot at `p` is free when `seq == p`: the consumer
76	    ///   released the previous lap by storing `pos + M`, which
77	    ///   is this lap's `p`. Anything else (not yet released, or
78	    ///   a peer-corrupted seq) reads as Full, never as a slot
79	    ///   the protocol does not own.
80	    /// - Only `producer_idx` (ours, loaded once) and the slot's
81	    ///   seq are touched: the consumer's index line is never
82	    ///   read.
83	    /// - Guard semantics as v0's
84	    ///   [`WriteSlot`](crate::WriteSlot): one reservation at a
85	    ///   time, drop without commit abandons it.
86	    /// - `on_full` is called after each failed attempt with
87	    ///   the attempt count (0-based, saturating); returning
88	    ///   `false` gives up → `Err(Full)`. Pass `|_| false`
89	    ///   for a single non-blocking probe.
90	    pub fn reserve_slot_with<T>(
91	        &mut self,
92	        mut on_full: impl FnMut(u32) -> bool,
93	    ) -> Result<WriteSlot<'_, T>, Full>
94	    where
95	        T: FromBytes + IntoBytes + KnownLayout,
96	    {
97	        check_type::<T>(self.slot_size);
98	        // Ours alone: the consumer never reads or writes it.
99	        let p = self.header.producer_idx.load(Ordering::Relaxed);
100	        let mut attempt = 0u32;
101	        loop {
102	            // Acquire pairs with the consumer's Release release:
103	            // observing `p` means its reads of the previous lap
104	            // are done.
105	            if self.seq(p).load(Ordering::Acquire) == p {
106	                break;
107	            }
108	            if !on_full(attempt) {
109	                return Err(Full);
110	            }
111	            attempt = attempt.saturating_add(1);
112	        }
113	        // Raw pointer, not `&mut T` — same argument-protector
114	        // rationale as v0's WriteSlot.
115	        let msg = slot_ptr(self.slots, p, self.mask, self.slot_size) as *mut T;
116	        Ok(WriteSlot {
117	            header: self.header,
118	            seq: self.seq(p),
119	            msg,
120	            next_idx: p.wrapping_add(1),
121	            committed_seq: p.wrapping_add(self.capacity).wrapping_add(1),
122	            _slot: PhantomData,
123	        })
124	    }
125	}
126	
127	/// A reserved write slot: `DerefMut` to write the message, then
128	/// [`commit`](WriteSlot::commit).
129	pub struct WriteSlot<'p, T> {
130	    /// The ring's control block (for the producer_idx store).
131	    header: &'p Header,
132	    /// The reserved slot's seq word (for the commit store).
133	    seq: &'p AtomicU32,
134	    /// The slot, viewed as the message type. Raw on purpose —
135	    /// see v0's `WriteSlot`.
136	    msg: *mut T,
137	    /// Value `producer_idx` takes on commit.
138	    next_idx: u32,
139	    /// Value the seq takes on commit (`pos + capacity + 1`):
140	    /// one past the next lap's claimable value, so committed
141	    /// and released stay distinct at `capacity == 1`, where
142	    /// Vyukov's `pos + 1` would equal `pos + M`.
143	    committed_seq: u32,
144	    /// Owns the `&'p mut` borrow of the producer.
145	    _slot: PhantomData<&'p mut T>,
146	}
147	
148	impl<T> Deref for WriteSlot<'_, T> {
149	    type Target = T;
150	    /// Read access to the in-slot message.
151	    fn deref(&self) -> &T {
152	        // SAFETY: msg is in-bounds and aligned (check_type +
153	        // cache-line slot base), any byte pattern is a valid T
154	        // (FromBytes bound at reserve_slot_with), and the seq
155	        // protocol gives this guard exclusive slot access until
156	        // commit.
157	        unsafe { &*self.msg }
158	    }
159	}
160	
161	impl<T> DerefMut for WriteSlot<'_, T> {
162	    /// Write access to the in-slot message.
163	    fn deref_mut(&mut self) -> &mut T {
164	        // SAFETY: as in deref; &mut self gives exclusivity of
165	        // the minted reference.
166	        unsafe { &mut *self.msg }
167	    }
168	}
169	
170	impl<T> WriteSlot<'_, T> {
171	    /// Publish the slot to the consumer.
172	    ///
173	    /// - `producer_idx` first (`Relaxed` — producer-private
174	    ///   resume state), the seq store last (`Release` — the
175	    ///   protocol-visible handoff the consumer acquires).
176	    pub fn commit(self) {
177	        self.header
178	            .producer_idx
179	            .store(self.next_idx, Ordering::Relaxed);
180	        self.seq.store(self.committed_seq, Ordering::Release);
181	    }
182	}

1	//! Consuming endpoint: [`Consumer`] finds the oldest committed
2	//! slot by its seq word, the [`ReadSlot`] guard reads it in
3	//! place and releases through the same word.
4	
5	use core::marker::PhantomData;
6	use core::ops::Deref;
7	use core::sync::atomic::{AtomicU32, Ordering};
8	use zerocopy::{FromBytes, Immutable, KnownLayout};
9	
10	use super::Header;
11	use crate::{Empty, USER_WORDS, check_type, slot_ptr};
12	
13	/// The consuming endpoint: `reserve_slot_with` the oldest
14	/// committed slot, read in place, `release`.
15	pub struct Consumer<'a> {
16	    /// The ring's control block.
17	    header: &'a Header,
18	    /// Base of the per-slot sequence array.
19	    seqs: *const AtomicU32,
20	    /// Base of the slot array.
21	    slots: *mut u8,
22	    /// Geometry snapshot (see [`Ring`](super::Ring)).
23	    slot_size: u32,
24	    /// Geometry snapshot; release stores `pos + capacity`.
25	    capacity: u32,
26	    /// Slot-position mask (`capacity - 1`).
27	    mask: u32,
28	    _region: PhantomData<&'a [u8]>,
29	}
30	
31	// SAFETY: the handle owns the consumer role; see the Producer
32	// Send rationale.
33	unsafe impl Send for Consumer<'_> {}
34	
35	impl<'a> Consumer<'a> {
36	    /// Build the handle from [`Ring::split`](super::Ring::split)'s
37	    /// geometry snapshot.
38	    pub(super) fn new(
39	        header: &'a Header,
40	        seqs: *const AtomicU32,
41	        slots: *mut u8,
42	        slot_size: u32,
43	        capacity: u32,
44	        mask: u32,
45	    ) -> Self {
46	        Consumer {
47	            header,
48	            seqs,
49	            slots,
50	            slot_size,
51	            capacity,
52	            mask,
53	            _region: PhantomData,
54	        }
55	    }
56	
57	    /// The header's app-owned scratch line — same contract as
58	    /// the v0 endpoints' `user()`.
59	    pub fn user(&self) -> &[AtomicU32; USER_WORDS] {
60	        &self.header.user
61	    }
62	
63	    /// The seq word for free-running position `idx`.
64	    fn seq(&self, idx: u32) -> &AtomicU32 {
65	        // SAFETY: idx is masked to < capacity, inside the seq
66	        // array validated at init/attach.
67	        unsafe { &*self.seqs.add((idx & self.mask) as usize) }
68	    }
69	
70	    /// Reserve the oldest unread slot as a `&T`, applying an
71	    /// injected wait policy: retry until a message arrives or
72	    /// the policy gives up → [`Empty`].
73	    ///
74	    /// - The slot at `c` is committed when `seq == c + M + 1`.
75	    ///   Anything else (not yet committed, or a peer-corrupted
76	    ///   seq) reads as Empty, never as a readable slot.
77	    /// - Only `consumer_idx` (ours, loaded once) and the slot's
78	    ///   seq are touched: the producer's index line is never
79	    ///   read.
80	    /// - Guard semantics as v0's [`ReadSlot`](crate::ReadSlot):
81	    ///   one reservation at a time, drop without release
82	    ///   re-delivers the same slot.
83	    /// - `on_empty` is called after each failed attempt with
84	    ///   the attempt count (0-based, saturating); returning
85	    ///   `false` gives up → `Err(Empty)`. Pass `|_| false`
86	    ///   for a single non-blocking probe.
87	    pub fn reserve_slot_with<T>(
88	        &mut self,
89	        mut on_empty: impl FnMut(u32) -> bool,
90	    ) -> Result<ReadSlot<'_, T>, Empty>
91	    where
92	        T: FromBytes + KnownLayout + Immutable,
93	    {
94	        check_type::<T>(self.slot_size);
95	        // Ours alone: the producer never reads or writes it.
96	        let c = self.header.consumer_idx.load(Ordering::Relaxed);
97	        let expected = c.wrapping_add(self.capacity).wrapping_add(1);
98	        let mut attempt = 0u32;
99	        loop {
100	            // Acquire pairs with the producer's Release commit:
101	            // observing expected means the fill is visible.
102	            if self.seq(c).load(Ordering::Acquire) == expected {
103	                break;
104	            }
105	            if !on_empty(attempt) {
106	                return Err(Empty);
107	            }
108	            attempt = attempt.saturating_add(1);
109	        }
110	        // Raw pointer, not `&T` — same argument-protector
111	        // rationale as v0's ReadSlot.
112	        let msg = slot_ptr(self.slots, c, self.mask, self.slot_size) as *const T;
113	        Ok(ReadSlot {
114	            header: self.header,
115	            seq: self.seq(c),
116	            msg,
117	            next_idx: c.wrapping_add(1),
118	            released_seq: c.wrapping_add(self.capacity),
119	            _slot: PhantomData,
120	        })
121	    }
122	}
123	
124	/// A reserved read slot: `Deref` to read the message, then
125	/// [`release`](ReadSlot::release).
126	pub struct ReadSlot<'c, T> {
127	    /// The ring's control block (for the consumer_idx store).
128	    header: &'c Header,
129	    /// The reserved slot's seq word (for the release store).
130	    seq: &'c AtomicU32,
131	    /// The slot, viewed as the message type. Raw on purpose —
132	    /// see v0's `ReadSlot`.
133	    msg: *const T,
134	    /// Value `consumer_idx` takes on release.
135	    next_idx: u32,
136	    /// Value the seq takes on release (`pos + capacity`):
137	    /// claimable again one lap later.
138	    released_seq: u32,
139	    /// Owns the `&'c` borrow of the consumer.
140	    _slot: PhantomData<&'c T>,
141	}
142	
143	impl<T> Deref for ReadSlot<'_, T> {
144	    type Target = T;
145	    /// Read access to the in-slot message.
146	    fn deref(&self) -> &T {
147	        // SAFETY: msg is in-bounds and aligned (check_type +
148	        // cache-line slot base), any byte pattern is a valid T
149	        // (FromBytes bound), and the seq protocol gives this
150	        // guard read access until release.
151	        unsafe { &*self.msg }
152	    }
153	}
154	
155	impl<T> ReadSlot<'_, T> {
156	    /// Free the slot for reuse.
157	    ///
158	    /// - `consumer_idx` first (`Relaxed` — consumer-private
159	    ///   resume state), the seq store last (`Release` — the
160	    ///   protocol-visible handoff the producer acquires).
161	    pub fn release(self) {
162	        self.header
163	            .consumer_idx
164	            .store(self.next_idx, Ordering::Relaxed);
165	        self.seq.store(self.released_seq, Ordering::Release);
166	    }
167	}

